// --- Pricing pipeline ---

describe("Cart pricing pipeline", () => {
  it("computes correct totals with defaults (no discount, no tax, free shipping)", () => {
    const cart = new Cart();
    cart.add(productA, 2); // 2 * 1000 = 2000
    cart.add(productB, 1); // 1 * 2000 = 2000
    const t = cart.totals();
    expect(t.subtotalCents).toBe(4000);
    expect(t.discountCents).toBe(0);
    expect(t.taxCents).toBe(0);
    expect(t.shippingCents).toBe(0);
    expect(t.totalCents).toBe(4000);
  });

  it("applies discount before tax (tax is on discounted subtotal)", () => {
    const discountPolicy = mockDiscount(500);
    const taxCalc: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(100),
    };
    const cart = new Cart({ discountPolicy, taxCalculator: taxCalc });
    cart.add(productA, 2); // subtotal = 2000
    const t = cart.totals();
    expect(t.subtotalCents).toBe(2000);
    expect(t.discountCents).toBe(500);
    // Tax should be called with discounted subtotal = 1500
    expect(taxCalc.computeTaxCents).toHaveBeenCalledWith(1500, "US");
    expect(t.taxCents).toBe(100);
    // total = discountedSubtotal + tax + shipping = 1500 + 100 + 0 = 1600
    expect(t.totalCents).toBe(1600);
  });

  it("clamps discount to [0, subtotal] — discount > subtotal clamped down", () => {
    const cart = new Cart({ discountPolicy: mockDiscount(99999) });
    cart.add(productA, 1); // subtotal = 1000
    const t = cart.totals();
    expect(t.discountCents).toBe(1000); // clamped to subtotal
    expect(t.totalCents).toBe(0);
  });

  it("clamps negative discount to 0", () => {
    const cart = new Cart({ discountPolicy: mockDiscount(-500) });
    cart.add(productA, 1); // subtotal = 1000
    const t = cart.totals();
    expect(t.discountCents).toBe(0);
    expect(t.totalCents).toBe(1000);
  });

  it("passes lines and discounted subtotal to shipping calculator", () => {
    const shippingCalc = mockShipping(300);
    const cart = new Cart({
      discountPolicy: mockDiscount(200),
      shippingCalculator: shippingCalc,
    });
    cart.add(productA, 1); // subtotal = 1000, discounted = 800
    cart.totals();
    expect(shippingCalc.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      800,
    );
  });

  it("clamps negative tax and shipping to 0", () => {
    const cart = new Cart({
      taxCalculator: mockTax(-100),
      shippingCalculator: mockShipping(-50),
    });
    cart.add(productA, 1);
    const t = cart.totals();
    expect(t.taxCents).toBe(0);
    expect(t.shippingCents).toBe(0);
  });

  it("totals for empty cart are all zeros", () => {
    const cart = new Cart();
    const t = cart.totals();
    expect(t).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("uses region from config for tax calculation", () => {
    const taxCalc = mockTax(0);
    const cart = new Cart({ taxCalculator: taxCalc, region: "FR" });
    cart.add(productA, 1);
    cart.totals();
    expect(taxCalc.computeTaxCents).toHaveBeenCalledWith(expect.any(Number), "FR");
  });

  it("defaults region to 'US'", () => {
    const taxCalc = mockTax(0);
    const cart = new Cart({ taxCalculator: taxCalc });
    cart.add(productA, 1);
    cart.totals();
    expect(taxCalc.computeTaxCents).toHaveBeenCalledWith(expect.any(Number), "US");
  });
});

