describe("CompositeDiscountPolicy", () => {
  it("rejects empty policies array", () => {
    expect(() => new CompositeDiscountPolicy([])).toThrow(
      "CompositeDiscountPolicy requires at least one policy",
    );
  });

  it("returns 0 for zero subtotal regardless of mode", () => {
    const composite = new CompositeDiscountPolicy(
      [new PercentageDiscountPolicy(50)],
      "sum",
    );
    expect(composite.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal regardless of mode", () => {
    const composite = new CompositeDiscountPolicy(
      [new PercentageDiscountPolicy(50)],
      "chain",
    );
    expect(composite.computeDiscountCents(-100)).toBe(0);
  });

  describe("sum mode", () => {
    it("sums discounts from all policies against the original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // 10% of 1000 = 100, fixed 200 => 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("can exceed subtotal (clamping is Cart's responsibility)", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(600), new FixedAmountDiscountPolicy(600)],
        "sum",
      );
      // Each caps at 1000, so 1000+1000 = 2000 (sum doesn't clamp internally per-policy to subtotal, but FixedAmount does cap at subtotal)
      // Actually FixedAmountDiscountPolicy caps at subtotal: min(600, 1000) = 600 each => 1200
      expect(composite.computeDiscountCents(1000)).toBe(1200);
    });

    it("defaults to sum mode when mode is omitted", () => {
      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(50),
      ]);
      // 10% of 1000 = 100, fixed 50 => 150
      expect(composite.computeDiscountCents(1000)).toBe(150);
    });

    it("clamps negative child results to 0 before summing", () => {
      // NoDiscountPolicy always returns 0, so this is a minimal sanity check
      const composite = new CompositeDiscountPolicy(
        [new NoDiscountPolicy(), new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      expect(composite.computeDiscountCents(500)).toBe(100);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially to the remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new PercentageDiscountPolicy(50)],
        "chain",
      );
      // First: 50% of 1000 = 500 discount, remaining = 500
      // Second: 50% of 500 = 250 discount, remaining = 250
      // Total discount = 750
      expect(composite.computeDiscountCents(1000)).toBe(750);
    });

    it("order matters in chain mode", () => {
      const policyA = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(300), new PercentageDiscountPolicy(50)],
        "chain",
      );
      const policyB = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new FixedAmountDiscountPolicy(300)],
        "chain",
      );
      // A: fixed 300 off 1000 => remaining 700, then 50% of 700 = 350 => total 650
      // B: 50% of 1000 = 500 => remaining 500, then fixed min(300,500)=300 => total 800
      expect(policyA.computeDiscountCents(1000)).toBe(650);
      expect(policyB.computeDiscountCents(1000)).toBe(800);
    });

    it("stops accumulating when remaining reaches 0", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(1000),
          new PercentageDiscountPolicy(50),
        ],
        "chain",
      );
      // Fixed 1000 off 1000 => remaining 0, 50% of 0 = 0 => total 1000
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });
  });
});
"}

