const productA: Product = { id: "a", name: "Alpha", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Beta", unitPriceCents: 2000, weightGrams: 500 };

function mockDiscount(amount: number): DiscountPolicy {
  return { computeDiscountCents: vi.fn().mockReturnValue(amount) };
}

function mockTax(amount: number): TaxCalculator {
  return { computeTaxCents: vi.fn().mockReturnValue(amount) };
}

function mockShipping(amount: number): ShippingCalculator {
  return { computeShippingCents: vi.fn().mockReturnValue(amount) };
}

// --- Cart line management ---

describe("Cart line management", () => {
  let cart: Cart;

  beforeEach(() => {
    cart = new Cart();
  });

  it("starts empty with itemCount 0", () => {
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toEqual([]);
  });

  it("adds a product", () => {
    cart.add(productA, 2);
    expect(cart.itemCount).toBe(2);
    const snap = cart.snapshot();
    expect(snap).toHaveLength(1);
    expect(snap[0].product.id).toBe("a");
    expect(snap[0].quantity).toBe(2);
  });

  it("merges quantity when adding the same product twice", () => {
    cart.add(productA, 2);
    cart.add(productA, 3);
    expect(cart.itemCount).toBe(5);
    expect(cart.snapshot()).toHaveLength(1);
    expect(cart.snapshot()[0].quantity).toBe(5);
  });

  it("keeps separate lines for different products", () => {
    cart.add(productA, 1);
    cart.add(productB, 2);
    expect(cart.itemCount).toBe(3);
    expect(cart.snapshot()).toHaveLength(2);
  });

  it("rejects non-positive quantity", () => {
    expect(() => cart.add(productA, 0)).toThrow(RangeError);
    expect(() => cart.add(productA, -1)).toThrow(RangeError);
    expect(() => cart.add(productA, 1.5)).toThrow(RangeError);
  });

  it("rejects negative unitPriceCents", () => {
    const bad: Product = { id: "x", name: "Bad", unitPriceCents: -1 };
    expect(() => cart.add(bad, 1)).toThrow(RangeError);
  });

  it("removes a product and returns true", () => {
    cart.add(productA, 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("returns false when removing unknown product", () => {
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity changes the quantity of an existing line", () => {
    cart.add(productA, 3);
    cart.updateQuantity("a", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("updateQuantity with 0 removes the line", () => {
    cart.add(productA, 3);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toHaveLength(0);
  });

  it("updateQuantity throws for unknown product", () => {
    expect(() => cart.updateQuantity("nonexistent", 5)).toThrow(
      "Product nonexistent is not in the cart",
    );
  });

  it("updateQuantity rejects negative quantity", () => {
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("updateQuantity rejects non-integer quantity", () => {
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
  });

  it("clear empties the cart", () => {
    cart.add(productA, 1);
    cart.add(productB, 2);
    cart.clear();
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toEqual([]);
  });

  it("snapshot returns a deep copy (mutations don't affect cart)", () => {
    cart.add(productA, 2);
    const snap = cart.snapshot();
    snap[0].quantity = 999;
    snap[0].product.unitPriceCents = 1;
    expect(cart.snapshot()[0].quantity).toBe(2);
    expect(cart.snapshot()[0].product.unitPriceCents).toBe(1000);
  });
});

// --- Pricing pipeline ---

describe("Cart pricing pipeline", () => {
  it("computes correct totals with defaults (no discount, no tax, free shipping)", () => {
    const cart = new Cart();
    cart.add(productA, 2); // 2 * 1000 = 2000
    cart.add(productB, 1); // 1 * 2000 = 2000
    const t = cart.totals();
    expect(t.subtotalCents).toBe(4000);
    expect(t.discountCents).toBe(0);
    expect(t.taxCents).toBe(0);
    expect(t.shippingCents).toBe(0);
    expect(t.totalCents).toBe(4000);
  });

  it("applies discount before tax (tax is on discounted subtotal)", () => {
    const discountPolicy = mockDiscount(500);
    const taxCalc: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(100),
    };
    const cart = new Cart({ discountPolicy, taxCalculator: taxCalc });
    cart.add(productA, 2); // subtotal = 2000
    const t = cart.totals();
    expect(t.subtotalCents).toBe(2000);
    expect(t.discountCents).toBe(500);
    // Tax should be called with discounted subtotal = 1500
    expect(taxCalc.computeTaxCents).toHaveBeenCalledWith(1500, "US");
    expect(t.taxCents).toBe(100);
    // total = discountedSubtotal + tax + shipping = 1500 + 100 + 0 = 1600
    expect(t.totalCents).toBe(1600);
  });

  it("clamps discount to [0, subtotal] — discount > subtotal clamped down", () => {
    const cart = new Cart({ discountPolicy: mockDiscount(99999) });
    cart.add(productA, 1); // subtotal = 1000
    const t = cart.totals();
    expect(t.discountCents).toBe(1000); // clamped to subtotal
    expect(t.totalCents).toBe(0);
  });

  it("clamps negative discount to 0", () => {
    const cart = new Cart({ discountPolicy: mockDiscount(-500) });
    cart.add(productA, 1); // subtotal = 1000
    const t = cart.totals();
    expect(t.discountCents).toBe(0);
    expect(t.totalCents).toBe(1000);
  });

  it("passes lines and discounted subtotal to shipping calculator", () => {
    const shippingCalc = mockShipping(300);
    const cart = new Cart({
      discountPolicy: mockDiscount(200),
      shippingCalculator: shippingCalc,
    });
    cart.add(productA, 1); // subtotal = 1000, discounted = 800
    cart.totals();
    expect(shippingCalc.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      800,
    );
  });

  it("clamps negative tax and shipping to 0", () => {
    const cart = new Cart({
      taxCalculator: mockTax(-100),
      shippingCalculator: mockShipping(-50),
    });
    cart.add(productA, 1);
    const t = cart.totals();
    expect(t.taxCents).toBe(0);
    expect(t.shippingCents).toBe(0);
  });

  it("totals for empty cart are all zeros", () => {
    const cart = new Cart();
    const t = cart.totals();
    expect(t).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("uses region from config for tax calculation", () => {
    const taxCalc = mockTax(0);
    const cart = new Cart({ taxCalculator: taxCalc, region: "FR" });
    cart.add(productA, 1);
    cart.totals();
    expect(taxCalc.computeTaxCents).toHaveBeenCalledWith(expect.any(Number), "FR");
  });

  it("defaults region to 'US'", () => {
    const taxCalc = mockTax(0);
    const cart = new Cart({ taxCalculator: taxCalc });
    cart.add(productA, 1);
    cart.totals();
    expect(taxCalc.computeTaxCents).toHaveBeenCalledWith(expect.any(Number), "US");
  });
});

// --- Async checkout ---

describe("Cart.checkout()", () => {
  it("returns totals and lines without collaborators", async () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.lines).toHaveLength(1);
    expect(result.lines[0].quantity).toBe(2);
  });

  describe("price refresh", () => {
    it("refreshes prices from priceFetcher before computing totals", async () => {
      const cart = new Cart();
      cart.add(productA, 1); // original 1000
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };
      const result = await cart.checkout({ priceFetcher });
      expect(result.totals.subtotalCents).toBe(1500);
      expect(result.lines[0].product.unitPriceCents).toBe(1500);
    });

    it("propagates priceFetcher rejection", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("price API down")),
      };
      await expect(cart.checkout({ priceFetcher })).rejects.toThrow("price API down");
    });
  });

  describe("inventory check", () => {
    it("succeeds when all items are available", async () => {
      const cart = new Cart();
      cart.add(productA, 2);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
      };
      const result = await cart.checkout({ inventoryChecker });
      expect(result.totals.subtotalCents).toBe(2000);
    });

    it("throws InventoryError when item is unavailable", async () => {
      const cart = new Cart();
      cart.add(productA, 2);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          reason: "discontinued",
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("a");
        expect(invErr.requested).toBe(2);
        expect(invErr.message).toBe("discontinued");
      }
    });

    it("throws InventoryError for partial-stock denial (availableQuantity < requested)", async () => {
      const cart = new Cart();
      cart.add(productA, 5);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 3,
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("a");
        expect(invErr.requested).toBe(5);
        expect(invErr.available).toBe(3);
      }
    });

    it("checks first denial wins (first product fails)", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      cart.add(productB, 1);
      const inventoryChecker: InventoryChecker = {
        check: vi
          .fn()
          .mockResolvedValueOnce({ available: false, reason: "out of stock" })
          .mockResolvedValueOnce({ available: true }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        // Second product should not have been checked
        expect(inventoryChecker.check).toHaveBeenCalledTimes(1);
      }
    });
  });

  describe("async tax provider", () => {
    it("uses asyncTaxProvider for tax computation during checkout", async () => {
      const cart = new Cart({
        discountPolicy: mockDiscount(0),
      });
      cart.add(productA, 1); // subtotal 1000
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.10),
      };
      const result = await cart.checkout({ asyncTaxProvider });
      expect(result.totals.taxCents).toBe(100); // 10% of 1000
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US");
    });

    it("applies discount before async tax", async () => {
      const cart = new Cart({
        discountPolicy: mockDiscount(200),
        region: "US-CA",
      });
      cart.add(productA, 1); // subtotal 1000, discounted = 800
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.10),
      };
      const result = await cart.checkout({ asyncTaxProvider });
      expect(result.totals.subtotalCents).toBe(1000);
      expect(result.totals.discountCents).toBe(200);
      expect(result.totals.taxCents).toBe(80); // 10% of 800
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
    });

    it("propagates asyncTaxProvider failure", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
      };
      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow("tax service down");
    });
  });

  describe("full pipeline: price refresh + inventory + async tax + shipping", () => {
    it("runs full pipeline in order", async () => {
      const cart = new Cart({
        discountPolicy: mockDiscount(100),
        shippingCalculator: mockShipping(500),
        region: "FR",
      });
      cart.add(productA, 2); // original subtotal = 2000

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1200),
      };
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.20),
      };

      const result = await cart.checkout({
        priceFetcher,
        inventoryChecker,
        asyncTaxProvider,
      });

      // After refresh: subtotal = 1200 * 2 = 2400
      expect(result.totals.subtotalCents).toBe(2400);
      // Discount clamped: min(max(0, 100), 2400) = 100
      expect(result.totals.discountCents).toBe(100);
      // Discounted subtotal = 2300
      // Tax: 20% of 2300 = 460
      expect(result.totals.taxCents).toBe(460);
      // Shipping = 500
      expect(result.totals.shippingCents).toBe(500);
      // Total = 2300 + 460 + 500 = 3260
      expect(result.totals.totalCents).toBe(3260);
    });
  });
});
"}

