import { describe, it, expect, vi } from "vitest";
import {
  InventoryError,
  refreshPrices,
  type PriceFetcher,
} from "../src/inventory.ts";
import type { CartLine } from "../src/product.ts";

describe("InventoryError", () => {
  it("exposes productId, requested, and available properties", () => {
    const err = new InventoryError("out of stock", "prod-1", 5, 2);
    expect(err.message).toBe("out of stock");
    expect(err.productId).toBe("prod-1");
    expect(err.requested).toBe(5);
    expect(err.available).toBe(2);
    expect(err.name).toBe("InventoryError");
    expect(err).toBeInstanceOf(Error);
  });

  it("supports undefined available quantity", () => {
    const err = new InventoryError("gone", "prod-2", 3, undefined);
    expect(err.available).toBeUndefined();
  });
});

describe("refreshPrices", () => {
  const makeLines = (): CartLine[] => [
    { product: { id: "p1", name: "Widget", unitPriceCents: 100 }, quantity: 2 },
    { product: { id: "p2", name: "Gadget", unitPriceCents: 200 }, quantity: 1 },
  ];

  it("updates each line's unitPriceCents from the fetcher", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn()
        .mockResolvedValueOnce(150)
        .mockResolvedValueOnce(250),
    };
    const result = await refreshPrices(makeLines(), fetcher);
    expect(result).toHaveLength(2);
    expect(result[0].product.unitPriceCents).toBe(150);
    expect(result[0].quantity).toBe(2);
    expect(result[1].product.unitPriceCents).toBe(250);
    expect(result[1].quantity).toBe(1);
  });

  it("preserves product properties other than unitPriceCents", async () => {
    const lines: CartLine[] = [
      {
        product: { id: "p1", name: "Widget", unitPriceCents: 100, weightGrams: 500, currency: "EUR" },
        quantity: 1,
      },
    ];
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(999),
    };
    const result = await refreshPrices(lines, fetcher);
    expect(result[0].product.weightGrams).toBe(500);
    expect(result[0].product.currency).toBe("EUR");
    expect(result[0].product.name).toBe("Widget");
  });

  it("calls fetchPriceCents with the product id", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(100),
    };
    await refreshPrices(makeLines(), fetcher);
    expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("p1");
    expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("p2");
  });

  it("throws RangeError for non-integer price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(10.5),
    };
    await expect(refreshPrices(makeLines(), fetcher)).rejects.toThrow(RangeError);
  });

  it("throws RangeError for negative price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(-1),
    };
    await expect(refreshPrices(makeLines(), fetcher)).rejects.toThrow(RangeError);
  });

  it("returns empty array for empty lines", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(100),
    };
    const result = await refreshPrices([], fetcher);
    expect(result).toEqual([]);
    expect(fetcher.fetchPriceCents).not.toHaveBeenCalled();
  });

  it("propagates fetcher rejection", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("network error")),
    };
    await expect(refreshPrices(makeLines(), fetcher)).rejects.toThrow("network error");
  });
});

